// sketch: four lines drawn a little off, joined, made horizontal and vertical, a corner fixed, 30 and 20 long by length constraints
export function c011(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s, "l1", { "start" : vector(0.3, -0.2) * millimeter, "end" : vector(29, 0.6) * millimeter });
    skLineSegment(s, "l2", { "start" : vector(29.4, 0.2) * millimeter, "end" : vector(30.5, 19) * millimeter });
    skLineSegment(s, "l3", { "start" : vector(30.2, 19.6) * millimeter, "end" : vector(0.4, 20.5) * millimeter });
    skLineSegment(s, "l4", { "start" : vector(-0.3, 20.2) * millimeter, "end" : vector(0.2, 0.3) * millimeter });
    skConstraint(s, "c1", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l1.end", "localSecond" : "l2.start" });
    skConstraint(s, "c2", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l2.end", "localSecond" : "l3.start" });
    skConstraint(s, "c3", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l3.end", "localSecond" : "l4.start" });
    skConstraint(s, "c4", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l4.end", "localSecond" : "l1.start" });
    skConstraint(s, "h1", { "constraintType" : ConstraintType.HORIZONTAL, "localFirst" : "l1" });
    skConstraint(s, "h3", { "constraintType" : ConstraintType.HORIZONTAL, "localFirst" : "l3" });
    skConstraint(s, "v2", { "constraintType" : ConstraintType.VERTICAL, "localFirst" : "l2" });
    skConstraint(s, "v4", { "constraintType" : ConstraintType.VERTICAL, "localFirst" : "l4" });
    skConstraint(s, "fix", { "constraintType" : ConstraintType.FIX, "localFirst" : "l1.start" });
    skConstraint(s, "len1", { "constraintType" : ConstraintType.LENGTH, "localFirst" : "l1", "length" : 30 * millimeter });
    skConstraint(s, "len2", { "constraintType" : ConstraintType.LENGTH, "localFirst" : "l2", "length" : 20 * millimeter });
    skSolve(s);
    return { "curves" : sketchProbe(context, id + "s") };
}

