    skLineSegment(s, "l1", { "start" : vector(0.2, 0.3) * millimeter, "end" : vector(20.5, -0.2) * millimeter });
    skArc(s, "a1", { "start" : vector(20.5, 0) * millimeter, "mid" : vector(25.5, 5.3) * millimeter, "end" : vector(20, 10.4) * millimeter });
    skLineSegment(s, "l2", { "start" : vector(20.3, 10) * millimeter, "end" : vector(-0.3, 9.6) * millimeter });
    skArc(s, "a2", { "start" : vector(0, 10.2) * millimeter, "mid" : vector(-4.6, 5) * millimeter, "end" : vector(0.1, -0.2) * millimeter });
    skConstraint(s, "c1", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l1.end", "localSecond" : "a1.start" });
    skConstraint(s, "c2", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "a1.end", "localSecond" : "l2.start" });
