// sketch: a fixed line from (0, 0) to (20, 10) and a point drawn at (9, 7), made its midpoint
export function c018(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
