    skConstraint(s, "fix", { "constraintType" : ConstraintType.FIX, "localFirst" : "l1" });
    skConstraint(s, "mid", { "constraintType" : ConstraintType.MIDPOINT, "localFirst" : "p", "localSecond" : "l1" });
    skLineSegment(s, "l2", { "start" : vector(9, 7) * millimeter, "end" : vector(9, 20) * millimeter });
    skConstraint(s, "co", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "p", "localSecond" : "l2.start" });
    skConstraint(s, "v", { "constraintType" : ConstraintType.VERTICAL, "localFirst" : "l2" });
    skConstraint(s, "len", { "constraintType" : ConstraintType.LENGTH, "localFirst" : "l2", "length" : 10 * millimeter });
    skSolve(s);
    return { "curves" : sketchProbe(context, id + "s") };
}

// sketch: a fixed line and a line drawn near its mirror image across a fixed vertical construction line at x = 10, made its mirror image
export function c019(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s, "axis", { "start" : vector(10, -5) * millimeter, "end" : vector(10, 25) * millimeter, "construction" : true });
    skLineSegment(s, "l1", { "start" : vector(2, 3) * millimeter, "end" : vector(6, 15) * millimeter });
    skLineSegment(s, "l2", { "start" : vector(17.5, 3.4) * millimeter, "end" : vector(14.3, 14.6) * millimeter });
