    skConstraint(s, "m", { "constraintType" : ConstraintType.MIRROR, "localMirror" : "axis", "localFirst" : "l1", "localSecond" : "l2" });
    skSolve(s);
    return { "curves" : sketchProbe(context, id + "s") };
}

